"""Verification sets for gate check G5: generated by CODE ONLY (Latin-hypercube coverage over the frozen ranges).

No LLM is involved, so a model can never influence them; they are never shown to the analyst or fixer. The sampler is the
same one used by the ceiling search and the dev sweeps (latin_hypercube), because the 0.90 target was calibrated on
broad sweeps, not on the generator's risk-weighted mix. This module is under app/gate/, the only place allowed to pass
held_out=True.
"""
from __future__ import annotations

from dataclasses import dataclass

from ..core.gate_config import GATE_HELDOUT_SIZE
from ..core.schemas import Scenario
from ..scenarios.sweep import latin_hypercube
from ..store.ledger import SeedLedger


@dataclass
class VerificationSet:
    scenarios: list[Scenario]
    block_name: str  # "rehearsal" or "held_out"
    start: int
    count: int
    rehearsal: bool
    sampler: str = "latin_hypercube"
    consumed: bool = False  # set by the gate when G5 runs on it; a set can be verified against exactly once

    @property
    def held_out(self) -> bool:
        return self.block_name == "held_out"


def make_verification_set(ledger: SeedLedger, run_id: str, rehearsal: bool, n: int = GATE_HELDOUT_SIZE) -> VerificationSet:
    """Allocate a fresh single-use block from the ledger and sample `n` scenarios from it."""
    block = "rehearsal" if rehearsal else "held_out"
    start = ledger.allocate(run_id, block, n, purpose="G5 verification set", rehearsal=rehearsal)
    scns = latin_hypercube(n, sweep_seed=start, tag="verify", seed_base=start, held_out=not rehearsal)
    return VerificationSet(scenarios=scns, block_name=block, start=start, count=n, rehearsal=rehearsal)
